// 覆盖 jekyll-theme-chirpy v7.6.0 的 _javascript/pwa/app.js（升级主题时需重新比对）。
// 新版 sw.min.js 为网络优先且安装后立即接管，页面拿到的始终是最新内容，
// 因此不再弹出 "Update" 提示，也不需要在 Service Worker 切换时刷新页面。
(function () {
  if (!('serviceWorker' in navigator)) {
    return;
  }

  // Get Jekyll config from URL parameters
  const src = new URL(document.currentScript.src);
  const register = src.searchParams.get('register');
  const baseUrl = src.searchParams.get('baseurl');

  if (register) {
    navigator.serviceWorker.register(`${baseUrl}/sw.min.js`);
  } else {
    navigator.serviceWorker.getRegistrations().then((registrations) => {
      for (const registration of registrations) {
        registration.unregister();
      }
    });
  }
})();
